class Sailing:
    id: str
    route: str
    day: date
    seats: int
    deck_cm: int


@dataclass
class Booking:
    id: str
    sailing_id: str
    passengers: tuple
    vehicle: object  # Vehicle or None
    fare_cents: int
    status: str = "confirmed"

